// Controlled example with state
const ControlledExample = (args: any) => {
  const [value, setValue] = useState(args.value || "");
  const [ensName, setEnsName] = useState(args.ensName || "");

  return (
    <Box css={{ p: '$lg', maxWidth: '500px' }}>
      <Flex css={{ flexDirection: 'column', gap: '$md' }}>
        <ENSInputField
          {...args}
          value={value}
          ensName={ensName}
          handleOnChange={(newValue) => {
            setValue(newValue);
            // Simulate ENS resolution
            if (newValue.endsWith('.eth')) {
              setEnsName(newValue);
            }
            args.handleOnChange?.(newValue);
          }}
        />
        <Text variant="metadata" css={{ color: '$textMiddle' }}>
          Current value: {value || '(empty)'}
        </Text>
      </Flex>
    </Box>
  );
};

